import os
import re
import unittest

from textkit.cli import COMMANDS

README = os.path.join(os.path.dirname(__file__), "..", "README.md")


def readme_cells():
    cells = {}
    with open(README, encoding="utf-8") as f:
        for line in f:
            m = re.match(r"\|\s*`([^`]+)`\s*\|\s*(.*?)\s*\|\s*$", line)
            if m:
                cells[m.group(1)] = m.group(2)
    return cells


class DocSyncTest(unittest.TestCase):
    def test_readme_matches_help(self):
        cells = readme_cells()
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, cells, "missing README row")
                self.assertEqual(cells[name], c["help"])


if __name__ == "__main__":
    unittest.main()
"""The README command table and the registry must agree."""
import pathlib
import re
import unittest

from textkit.cli import COMMANDS

ROOT = pathlib.Path(__file__).resolve().parent.parent


class DocsTest(unittest.TestCase):
    def test_readme_table_matches_registry(self):
        readme = (ROOT / "README.md").read_text()
        table = set(re.findall(r"^\| `([a-z]+)` \|", readme, flags=re.M))
        self.assertEqual(table, set(COMMANDS))
